const { ui: C, space: S, type: Y } = T
const px = v => Math.round(parseFloat(v) * 100) / 100
const up = a => a.map(c => c.toUpperCase())
// a computed colour as #RRGGBB, '#RRGGBB@a' when translucent
const hex = c => {
  const m = c.match(/[\d.]+/g)
  if (!m || (m[3] !== undefined && +m[3] === 0)) return 'transparent'
  return '#' + m.slice(0, 3).map(v => (+v).toString(16).padStart(2, '0'))
    .join('').toUpperCase() + (m[3] !== undefined && +m[3] < 1
    ? `@${+m[3]}` : '')
}
const GREYS = up([C.text, C.textSecondary, C.inactive, C.border])
const MAP = up(Object.values(T.map))
const HEAD = px(Y.introHeading)
const SIZES = [Y.text, Y.introBody, Y.introHeading].map(px)
// the spacing the guidelines name and what was measured off their drawings:
// every space token that is not the size of a thing
const SIZES_NOT_SPACE = ['dotInactive', 'dotActive', 'dotHit', 'sliderThumb',
  'infoButton', 'keyMark', 'sliderValue', 'logo', 'chevronTop', 'dotInset',
  'underlineOffset']
const SPACE = [...new Set([0, ...Object.entries(S)
  .filter(([k, v]) => !SIZES_NOT_SPACE.includes(k) && /px$/.test(v))
  .map(([, v]) => px(v))])].sort((a, b) => a - b)

// a short path to an element, through shadow roots
const at = el => {
  const out = []
  for (let e = el; e && out.length < 4;) {
    out.unshift(e.localName + (e.id ? '#' + e.id : '') + [...e.classList]
      .slice(0, 2).map(c => '.' + c).join(''))
    e = e.parentElement ?? e.getRootNode?.().host
  }
  return out.join(' > ')
}
// the element whose style draws a text node: slotted text is drawn in its
// slot's parent, not in the host that holds it
const styled = n => {
  let e = n.parentElement
  for (let x = n; x.assignedSlot; x = x.assignedSlot)
    e = x.assignedSlot.parentElement
  return e
}
function* walk(root, skip) {
  for (const el of root.querySelectorAll('*')) {
    if (skip && el.matches(skip)
      || el.closest('.maplibregl-canvas-container')) continue
    yield el
    if (el.shadowRoot) yield* walk(el.shadowRoot, skip)
  }
}
// 14px and 32px are the intro panel's (pdf:77); every other ui text is 11px
const intro = el => {
  for (let e = el; e; e = e.parentElement ?? e.getRootNode().host)
    if (e.matches('[intro], .dd-intro-heading, .dd-intro-body')) return true
  return false
}
const onMap = el => !!(el.closest('dd-label, .maplibregl-marker, '
  + '.maplibregl-popup') || el.getRootNode().host?.closest?.('dd-label'))

export function audit(root = document.body, { map, allow = {} } = {}) {
  const found = [], seen = new Set()
  const flag = (rule, where, got, want) => {
    const a = typeof where === 'string' ? where : at(where)
    if (seen.has(rule + a + got)) return
    seen.add(rule + a + got)
    found.push({ rule, at: a, got: String(got), want: String(want) })
  }
  const extra = up(allow.colors ?? [])
  const sizes = el => [...intro(el) ? SIZES : [px(Y.text)],
    ...allow.sizes ?? []]
  // the ui greys, and the cartography palette where colour means something
  // (a status, a label in its feature's colour: pdf:83, 92)
  const INKS = new Set([...GREYS, ...MAP, C.activeText.toUpperCase(),
    ...extra])

  const type = el => {
    const s = getComputedStyle(el), svg = el instanceof SVGElement
    const fam = s.fontFamily.split(',')[0].replace(/["']/g, '').trim()
    if (!/^Inter(Variable)?$/.test(fam))
      flag('type: Inter only', el, fam, 'Inter')
    const size = px(s.fontSize), w = +s.fontWeight
    if (!sizes(el).includes(size))
      flag('type: size', el, size + 'px', sizes(el))
    if (w !== Y.regular && !(w === Y.bold && size === HEAD))
      flag('type: weight', el, w,
        `${Y.regular}; ${Y.bold} for the intro heading`)
    if (svg) return
    if (Math.abs(px(s.lineHeight) - size * Y.leading) > 0.6)
      flag('type: leading', el, s.lineHeight, `${Y.leading} × ${size}px`)
    if (s.letterSpacing !== 'normal' && size !== HEAD)
      flag('type: tracking', el, s.letterSpacing, 'normal')
    if (!Y.features.every(f => s.fontFeatureSettings.includes(f)
      || s.fontFeatureSettings === 'normal'))
      flag('type: features', el, s.fontFeatureSettings, Y.features)
    const o = s.fontVariationSettings.match(/"opsz" ([\d.]+)/)?.[1]
    if (Y.opsz[size] && +o !== Y.opsz[size])
      flag('type: optical size', el, o ?? 'auto', Y.opsz[size])
    const c = hex(s.color)
    if (c !== 'transparent' && !INKS.has(c))
      flag('colour: text', el, c, 'ui greys, cartography palette')
  }

  const box = el => {
    const s = getComputedStyle(el)
    if (el instanceof SVGElement) {
      for (const p of ['fill', 'stroke']) {
        const c = s[p] === 'none' ? 'transparent' : hex(s[p]).split('@')[0]
        if (c !== 'transparent' && !INKS.has(c))
          flag(`colour: svg ${p}`, el, c, 'palette')
      }
      return
    }
    const bg = hex(s.backgroundColor), b = el.getBoundingClientRect()
    const dot = Math.max(b.width, b.height) <= px(S.dotActive)
    if (bg !== 'transparent' && !up([C.background, C.hover,
      C.activeBackground, ...dot ? [C.inactive] : []]).concat(extra)
      .includes(bg))
      flag('colour: background', el, bg,
        [C.background, C.hover, C.activeBackground])
    for (const side of ['Top', 'Right', 'Bottom', 'Left']) {
      const w = px(s[`border${side}Width`]), st = s[`border${side}Style`]
      if (!w || st === 'none') continue
      const c = hex(s[`border${side}Color`])
      if (w !== 1 || st !== 'solid'
        || c !== C.border.toUpperCase() && !(onMap(el) && INKS.has(c)))
        flag('border', el, `${w}px ${st} ${c}`, `1px solid ${C.border}`)
    }
    const r = px(s.borderTopLeftRadius)
    if (r && Math.max(b.width, b.height) > px(S.infoButton))
      flag('corners: square', el, r + 'px', '0; round only up to 10px')
    if (s.boxShadow !== 'none') flag('no shadow', el, s.boxShadow, 'none')
    if (s.textShadow !== 'none') flag('no shadow', el, s.textShadow, 'none')
    if (+s.opacity < 1) flag('no opacity', el, s.opacity, 1)
    for (const p of ['paddingTop', 'paddingRight', 'paddingBottom',
      'paddingLeft', 'rowGap', 'columnGap']) {
      const v = px(s[p])
      if (!isNaN(v) && !SPACE.includes(v))
        flag('spacing', el, `${p} ${v}px`, SPACE.join('|'))
    }
  }

  for (const el of walk(root, allow.skip)) {
    if (!el.checkVisibility()) continue
    box(el)
    for (const n of el.childNodes)
      if (n.nodeType === 3 && n.textContent.trim()) {
        const t = styled(n)
        if (t?.checkVisibility()) type(t)
      }
  }
  if (root.querySelector('[intro], .dd-intro-heading')
    && root.ownerDocument?.fonts
    && ![...root.ownerDocument.fonts].some(f => /^"?Inter/.test(f.family)
      && f.status === 'loaded' && f.weight.split(' ').some(w => +w >= Y.bold)))
    flag('type: weight', 'document', 'no bold face loaded (synthesised)',
      `Inter ${Y.bold}`)
  if (map) mapRules(map, flag, allow)
  return found
}

// layers a page adds over the basemap: colour from the cartography palette,
// no maplibre text (its glyphs are not Inter), imagery graded
function mapRules(map, flag, allow) {
  const ok = new Set([...MAP, ...up(allow.colors ?? [])])
  const style = map.getStyle()
  for (const l of style.layers) {
    if (T.basemapLayers.includes(l.id)) continue
    const where = `layer ${l.id}`
    for (const c of JSON.stringify([l.paint, l.layout])
      .match(/#[0-9a-f]{6}\b|#[0-9a-f]{3}\b|rgba?\([^)]*\)/gi) ?? []) {
      const h = !c.startsWith('#') ? hex(c).split('@')[0]
        : c.length === 4 ? '#' + [...c.slice(1)].map(d => d + d).join('')
          : c
      if (h !== 'transparent' && !ok.has(h.toUpperCase()))
        flag('map: colour', where, h.toUpperCase(), 'cartography palette')
    }
    if (l.type === 'symbol' && l.layout?.['text-field']
      && !allow.glyphs?.includes(l.id))
      flag('map: text', where, l.layout['text-font'] ?? 'default font',
        'dd-label: Inter, title underlined')
    if (l.type === 'raster' && !allow.graded?.includes(l.id)
      && !(style.sources[l.source]?.tiles ?? []).some(t => /^dd/.test(t)))
      flag('map: imagery', where,
        `saturation ${l.paint?.['raster-saturation'] ?? 0}`, 'dd.grade')
  }
}

// the list grouped by rule, for a console or a ci log
export function report(root, opts) {
  const f = audit(root, opts)
  console.log(`dd audit: ${f.length} finding${f.length === 1 ? '' : 's'}`)
  console.table(f)
  return f
}
